/// Renders an inline SVG vector icon whose stroke/fill tracks `color`.
pub fn svg_icon(
    markup: &'static str,
    size: f32,
    color: impl Fn() -> AdaptiveColor + 'static,
) -> impl IntoElement {
    svg(ImageSrc::svg_markup(markup))
        .size(px(size))
        .text_color(color)
}

/// Encodes PNG bytes into a `data:image/png;base64,...` [`ImageSrc`] suitable
/// for system tray icons or embedded images.
pub fn png_data_uri(png_bytes: &[u8]) -> ImageSrc {
    let b64 = base64::engine::general_purpose::STANDARD.encode(png_bytes);
    ImageSrc::from(format!("data:image/png;base64,{b64}"))
}
